    p=dict(id='H3as-exact-finite-positive-recovery-reliability',frozen_utc=now(),hypothesis='Under uniform sampling without replacement, 16 distinct raw positive N12 labels uniquely select the correct graph by H3ar finite-candidate likelihood with probability at least99percent for BOTH fixed families.',families=[dict(name=name,leaper=list(o),source_path=f'results/research/loki/h3ad/b{i}/source-columns.npy') for i,(name,o) in enumerate([('queen-plus-zebra',(2,3)),('queen-plus-2-5-leaper',(2,5))])],candidate_prior=dict(orbits=[list(o) for o in itertools.combinations(range(1,6),2)],candidate_sizes=[0,1,2],candidate_count=56,base='Supplied ordinary queens; explicit D4 symmetry, radius5 vocabulary and atmost2orbits. Same prior as H3ar.'),source_selection_path='results/research/loki/h3ar/source-selection.json',ordinary_source_path='results/research/loki/h3ar/candidate0/source-columns.npy',doses=[4,8,16,32,64],primary=dict(dose=16,probability_threshold=[99,100],all_families=True),observation='Unordered uniform distinct subsets without replacement; candidate likelihood0 if inconsistent, otherwise1/choose(candidateN12cardinality,dose); retain every tied maximizer. No independent-orbit approximation.',lemma='Unique true graph recovery iff all nine other vocabulary orbits are witnessed. An unwitnessed other orbit permits true+other: if it excludes any true-population board it strictly improves likelihood; otherwise it ties true and defeats uniqueness because its graph is distinct. If all others witnessed only empty/true survive; proper true source population beats empty. Check graph distinctness, strict properness and zero-observability explicitly; zero-observability is retained as failed recovery, never dropped.',comparison='Consistency envelope exactly equals true graph under the same full-witness event; report identical recovery probability, not a likelihood-normalization advantage. BP AdamW is not fitted at any dose.',calculation='Exact nine-bit joint population witness histogram; integer subsetzeta/Mobius inversion yields every512union mass at every dose. Independently grouped withoutreplacement DP with binomial group weights must match every mass. Exhaustive small toy populations checked during charged run. Full512patterns directly classified under all56candidates to verify lemma, preserving allties and zero masses.',evaluation='Source-only finite-population calculation; no new draws, target truth data, target scores, exclusions or GPU searches. N12/N13 candidate graph distinctness is literal rule construction, not target data. Complete source population is evaluator information for exact reliability, not extra learner labels.',history='H3ar succeeded for eight previouslyexamined16label banks with control-identical graphs. This prospective probability test covers all possible draws from the same two known finite source populations, under a fixed supplied rule prior; no claim over new families or observation models.',budget=dict(aggregate_CPU_seconds=120,wall_seconds=180,GPUs=0,enforcement='Whole-study cap with all masses retained; stop entire study on ceiling with no pruning. Freeze/preparation and public audit separately reported.'),source_sha256={str(path.relative_to(ROOT)):sha(path) for path in files},source_data_sha256={str(path.relative_to(ROOT)):sha(path) for path in data})
